const out = [];
for (const item of items) {
  const p = item.json;
  const props = p.properties || p;
  const title =
    props.Name?.title?.[0]?.plain_text ||
    props['Engagement Name']?.title?.[0]?.plain_text ||
    props.Name?.title?.[0]?.text?.content ||
    p.name ||
    'Engagement';
  const client =
    props.Client?.rich_text?.[0]?.plain_text ||
    props.Client?.select?.name ||
    props['Client Name']?.rich_text?.[0]?.plain_text ||
    title;
  const fiscal =
    props['Fiscal Year']?.number ||
    props.FY?.number ||
    2025;
  const fee =
    props.Fee?.number ??
    props['Fee Amount']?.number ??
    props['Fee (EUR)']?.number ??
    null;
  const codeRaw =
    props.Code?.rich_text?.[0]?.plain_text ||
    props.Code?.select?.name ||
    null;
  // Derive a stable code if Notion has none
  const code =
    codeRaw ||
    String(client)
      .toUpperCase()
      .replace(/[^A-Z0-9]+/g, '-')
      .replace(/^-|-$/g, '')
      .slice(0, 12) + '-' + String(fiscal).slice(-2);
  out.push({
    json: {
      notion_page_id: p.id || p.page_id,
      name: title,
      client_name: client,
      code,
      fiscal_year: fiscal,
      fee_amount: fee,
      fee_currency: 'EUR',
      billing_model: 'fixed',
      kind: 'client',
      billable_default: true,
      status: 'active',
    },
  });
}
return out;
